package app.yoru.mobile;

import android.Manifest;
import android.app.*;
import android.content.pm.PackageManager;
import android.os.Build;
import android.text.InputType;
import android.widget.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;

public final class DownloadActions {
    private DownloadActions(){}
    public static void askEpisode(Activity activity,Anime anime,Anime.Playback current,double suggested){LinearLayout content=Ui.column(activity);content.setPadding(Ui.dp(activity,24),Ui.dp(activity,12),Ui.dp(activity,24),0);content.addView(Ui.text(activity,"Какую серию сохранить?",13,Ui.MUTED,false));EditText input=new EditText(activity);input.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);input.setText(Ui.number(suggested>0?suggested:1));input.setSingleLine();content.addView(input,Ui.lp(activity,-1,50));content.addView(Ui.text(activity,"Будет загружен прямой MP4/HLS/DASH-поток. Приложение проверит доступные озвучки, студии и качества.",11,Ui.MUTED,false));new AlertDialog.Builder(activity).setTitle("Скачать серию").setView(content).setPositiveButton("Выбрать качество",(d,w)->{try{double n=Double.parseDouble(input.getText().toString());if(!Double.isFinite(n)||n<0||n>100000)throw new Exception();prepare(activity,anime,current,n);}catch(Exception e){Ui.toast(activity,"Введите номер серии");}}).setNegativeButton("Отмена",null).show();}
    public static void prepare(Activity activity,Anime anime,Anime.Playback current,double episode){AtomicBoolean cancelled=new AtomicBoolean(false);ProgressDialog wait=new ProgressDialog(activity);wait.setMessage("Ищем все варианты для загрузки…");wait.setCancelable(true);wait.setOnCancelListener(d->cancelled.set(true));wait.show();YoruApp.app().io.execute(()->{try{List<ApiRepository.DownloadOption> options=YoruApp.app().api.downloadOptions(anime,current,episode);YoruApp.app().main.post(()->{if(activity.isFinishing()||activity.isDestroyed()||cancelled.get())return;wait.dismiss();if(options.isEmpty()){new AlertDialog.Builder(activity).setTitle("Нет доступного варианта для скачивания").setMessage("У текущих источников не найден прямой видеопоток этой серии. Можно выбрать YummyAnime, AniLiberty, AnimeVost, AniLib, AnimeGO или AniMedia в каталоге. Защищённые онлайн-плееры не подменяются пустыми загрузками.").setPositiveButton("Понятно",null).show();return;}String[] labels=new String[options.size()];int preferred=YoruApp.app().savingMobile()?480:YoruApp.app().store.quality(),index=0,best=-1;for(int i=0;i<options.size();i++){labels[i]=options.get(i).label();int q=options.get(i).quality;if(q>0&&q<=preferred&&q>best){best=q;index=i;}}final int[] selected={index};new AlertDialog.Builder(activity).setTitle("Серия "+Ui.number(episode)+" · качество").setSingleChoiceItems(labels,index,(d,i)->selected[0]=i).setPositiveButton("Скачать",(d,i)->confirm(activity,anime,options.get(selected[0]))).setNegativeButton("Отмена",null).show();});}catch(Exception e){YoruApp.app().main.post(()->{if(!activity.isFinishing()&&!activity.isDestroyed()&&!cancelled.get()){wait.dismiss();Ui.toast(activity,"Не удалось подготовить загрузку. Попробуйте другой источник.");}});}});}
    private static void confirm(Activity a,Anime anime,ApiRepository.DownloadOption option){Runnable run=()->{if(Build.VERSION.SDK_INT>=33&&a.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},4101);YoruApp.app().downloads().enqueue(anime,option.source,option.episode,option.quality);};if(YoruApp.app().traffic.metered()&&!YoruApp.app().store.wifiDownloads())new AlertDialog.Builder(a).setTitle("Использовать мобильную / платную сеть?").setMessage("Размер серии может составлять сотни мегабайт. Можно включить загрузки только по Wi-Fi в профиле.").setPositiveButton("Скачать",(d,w)->run.run()).setNegativeButton("Отмена",null).show();else run.run();}
}
